// TestimonialGrid.jsx
import React, { useRef } from "react";

/*
Usage: <TestimonialGrid videos={[ "/assets/test1.mp4", ... ]} />
Each card has its own play/pause since we use the native controls.
*/
export default function TestimonialGrid({ videos = [] }) {
  const refs = useRef([]);

  function pauseAll(exceptIndex = -1) {
    refs.current.forEach((rv, i) => {
      if (!rv) return;
      if (i === exceptIndex) return;
      rv.pause();
    });
  }

  return (
    <div className="testimonials card">
      <h3>Testimonial Videos</h3>
      <div className="test-row">
        {videos.map((src, i) => (
          <div className="test-card" key={i}>
            <video
              ref={(el) => (refs.current[i] = el)}
              src={src}
              width="100%"
              height="160"
              controls
              preload="metadata"
              playsInline
              onPlay={() => pauseAll(i)}
            />
          </div>
        ))}
      </div>
    </div>
  );
}











